578	func prepareSnapshot(ctx context.Context, repo string, options ProviderSnapshotOptions) (snapshotInputs, error) {
579		absRepo, err := filepath.Abs(repo)
580		if err != nil {
581			return snapshotInputs{}, err
582		}
583		key := repoKey(ctx, absRepo)
584		var warnings []ProviderWarning
585		commit, commitErr := gitutil.RevParse(ctx, absRepo, "HEAD")
586		tree, treeErr := gitutil.RevParse(ctx, absRepo, "HEAD^{tree}")
587	
588		// The provider is local-only. NoNetwork is accepted to make that contract
589		// explicit for callers that enforce no-egress provider execution.
590		_ = options.NoNetwork
591		useHead := !options.Worktree && commitErr == nil && treeErr == nil
592		paths, contentByFile, err := snapshotSource(ctx, absRepo, useHead, options.IgnoreFiles, options.IncludeFiles)
593		if err != nil {
594			return snapshotInputs{}, err
595		}
596		if options.Worktree {
597			warnings = append(warnings, ProviderWarning{
